"Як користуватися ботом":"How to use the bot",
"DnD Companion — листи персонажів D&D 5e, інвентар і кімнати для майстра та гравців прямо в Telegram. Натисни «Почати», щоб відкрити застосунок.":"DnD Companion — D&D 5e character sheets, inventory and rooms for the DM and players right in Telegram. Tap “Start” to open the app.",
"Листи персонажів, інвентар і кімнати D&D 5e для майстра та гравців.":"D&D 5e character sheets, inventory and rooms for the DM and players.",
"Як грати:":"How to play:",
"🧙 Майстер: відкрий застосунок → «Майстер» → створи кімнату → надішли гравцям посилання-запрошення.":"🧙 DM: open the app → “Dungeon Master” → create a room → send your players the invite link.",
"⚔️ Гравець: відкрий запрошення або введи код кімнати → створи персонажа.":"⚔️ Player: open the invite or enter the room code → create a character.",
"Майстер бачить усіх персонажів, видає предмети з каталогу D&D 5e, змінює характеристики, нараховує досвід. Гравці бачать лише свій лист і інвентар.":"The DM sees every character, hands out items from the D&D 5e catalog, edits stats and awards XP. Players only see their own sheet and inventory.",
